export type RecipeConfig<T, R> = {
  options: T
  execute: (options: Partial<T>) => Promise<R>
}

export type RecipeApi<T extends Record<string, any>, R> = Promise<R> & {
  [K in keyof T]: T[K] extends boolean ? (value?: boolean) => RecipeApi<T, R> : (value: T[K]) => RecipeApi<T, R>
}

export class Recipe {
  static builder = <T extends Record<string, any>, R>(opts: T, cb: (opts: Partial<T>) => Promise<R>) =>
    Recipe.create<T, R>(opts, (op) => cb(op))

  static create = <T extends Record<string, any>, R>(config: T, executer: (options: Partial<T>) => Promise<R>) => {
    const createBuilder = (executer: (options: Partial<T>) => Promise<R>, options: Partial<T>) => {
      let executionPromise: Promise<R> | null = null

      const execute = () => {
        if (!executionPromise) executionPromise = executer(options)
        return executionPromise
      }

      return new Proxy(
        {},
        {
          get(_, prop) {
            console.log({ prop })
            if (prop === 'then' || prop === 'catch' || prop === 'finally') {
              const promise = execute()
              const method = promise[prop]
              return method.bind(promise)
            }

            if (typeof prop === 'string' && prop in config) {
              return (value: any) => createBuilder(executer, { ...options, [prop]: value ?? config[prop as keyof T] })
            }

            return undefined
          },
        },
      )
    }

    return (opts?: Partial<T>) => createBuilder(executer, opts ?? {}) as RecipeApi<T, R>
  }
}
